    20          unsigned int i;
    21
    22          for (i = 0; i < 48; i++) {
    23                  inst->Operands[i].Kind = kInvalid;
    24          }
    25
    26          inst->Opcode = 0;
    27          inst->OpcodePub = 0;
    28          inst->size = 0;
    29          inst->has_imm = false;
    30          inst->op1_size = 0;
    31          inst->writeback = false;
    32          inst->ac_idx = 0;
