    87  /// MCInst - Instances of this class represent a single low-level machine
    88  /// instruction.
    89  struct MCInst {
    90          unsigned OpcodePub;
    91          uint8_t size;   // number of operands
    92          bool has_imm;   // indicate this instruction has an X86_OP_IMM operand - used for ATT syntax
    93          uint8_t op1_size; // size of 1st operand - for X86 Intel syntax
    94          unsigned Opcode;
    95          MCOperand Operands[48];
    96          cs_insn *flat_insn;     // insn to be exposed to public
    97          uint64_t address;       // address of this insn
    98          cs_struct *csh; // save the main csh
    99          uint8_t x86opsize;      // opsize for [mem] operand
   100
   101          // These flags could be used to pass some info from one target subcomponent
   102          // to another, for example, from disassembler to asm printer. The values of
   103          // the flags have any sense on target level only (e.g. prefixes on x86).
   104          unsigned flags;
   105
   106          // (Optional) instruction prefix, which can be up to 4 bytes.
   107          // A prefix byte gets value 0 when irrelevant.
   108          // This is copied from cs_x86 struct
   109          uint8_t x86_prefix[4];
   110          uint8_t imm_size;       // immediate size for X86_OP_IMM operand
   111          bool writeback; // writeback for ARM
   112          // operand access index for list of registers sharing the same access right (for ARM)
   113          uint8_t ac_idx;
   114          uint8_t popcode_adjust;   // Pseudo X86 instruction adjust
   115          char assembly[8];       // for special instruction, so that we dont need printer
   116          unsigned char evm_data[32];     // for EVM PUSH operand
   117          cs_wasm_op wasm_data;    // for WASM operand
   118          MCRegisterInfo *MRI;
   119  };
